import json
s=json.load(open('run_trace/deseq2_tool_schema.json'))

def optstr(opts):
    out=[]
    if isinstance(opts, list):
        for o in opts[:20]:
            if isinstance(o, dict): out.append(str(o.get('value', o.get('label', o))))
            elif isinstance(o, (list,tuple)): out.append(str(o))
            else: out.append(str(o))
        return ', '.join(out)+(' ...' if len(opts)>20 else '')
    return str(type(opts).__name__)

def walk(obj, indent=0):
    pad='  '*indent
    if isinstance(obj, list):
        for x in obj: walk(x, indent)
        return
    if not isinstance(obj, dict): return
    print(f\"{pad}- {obj.get('name')"'!r} type={obj.get('"'type')"'!r} label={obj.get('"'label')"'!r} value={obj.get('"'value')"'!r} optional={obj.get('"'optional')"'!r}")
    if obj.get('"'options') is not None:
        print(pad+'  options: '+optstr(obj['options']))
    if 'inputs' in obj:
        walk(obj['inputs'], indent+1)
    if 'cases' in obj:
        for c in obj['cases']:
            print(pad+f\"  case value={c.get('value')"'!r} label={c.get('"'label')"'!r}")
            walk(c.get('"'inputs',[]), indent+2)
walk(s['inputs'])
