from pathlib import Path
import csv, math, json
files={
 'full': Path('codex_output/galaxy_downloads/full_f9cad7b01a47213530b388e96a436314.dat'),
 'reduced': Path('codex_output/galaxy_downloads/reduced_f9cad7b01a47213507cf831e3782676c.dat'),
}
summary={}
for label,path in files.items():
    n=up=down=total=nan_rows=0
    with path.open(newline='') as f:
        r=csv.reader(f, delimiter='\\t')
        for row in r:
            if not row: continue
            total+=1
            if len(row)<6:
                nan_rows+=1; continue
            try:
                base=float(row[1]); lfc=float(row[2]); p=float(row[4])
            except ValueError:
                nan_rows+=1; continue
            if math.isnan(base) or math.isnan(lfc) or math.isnan(p):
                nan_rows+=1; continue
            if base>10 and p<0.05 and abs(lfc)>1:
                n+=1
                if lfc>0: up+=1
                elif lfc<0: down+=1
    summary[label]={'total_rows':total,'significant':n,'up':up,'down':down,'nan_or_nonnum':nan_rows}
full=summary['full']['significant']; reduced=summary['reduced']['significant']
direction='increase' if reduced>full else 'decrease' if reduced<full else 'no change'
answer=f'{full} {reduced} {direction}'
Path('codex_output/count_summary.json').write_text(json.dumps(summary, indent=2)+'\\n')
Path('codex_output/answer.txt').write_text(answer+'\\n')
print(json.dumps(summary, indent=2))
print('ANSWER', answer)
PY"

